export type ToolParams = {
  /** `select`, `rect`, `ellipse` or `text`. */
  tool: Tool;
};

/** A transform of `document.transform`. */
export type TransformOp = {
  /** `[dx, dy]`, mm. */
  translate: [number, number];
} | {
  /** `[x, y]`, mm. */
  pivot: [number, number];
  /** `[sx, sy]` (not zero). */
  scale: [number, number];
} | {
  /** `[x, y]`, mm. */
  pivot: [number, number];
  /** Degrees, counterclockwise. */
  rotate_deg: number;
} | {
  /** `[a, b, c, d, e, f]`. */
  matrix: [number, number, number, number, number, number];
};

export type TransformParams = {
  /** Object ids (default: the selection). */
  ids?: number[] | null;
  /** The transform. */
  op: TransformOp;
};

export type TranslateParams = {
  /** Distance along X, mm. */
  dx: number;
  /** Distance along Y, mm. */
  dy: number;
  /** Object ids (default: the selection). */
  ids?: number[] | null;
};

/** Appearance of the desktop app. */
export type UiSettings = {
  /** Density of the controls. */
  density?: Density;
  /** High contrast (on top of the theme). */
  high_contrast?: boolean;
  /** Language: `auto` (the system's) or a locale of `ui/i18n` (`en`, `pt-BR`, `de`...). */
  language?: string;
  /** Theme. */
  theme?: Theme;
  /** Units shown. */
  units?: Units;
};

/** Length units shown in the app (the machine always works in mm). */
export type Units = "mm" | "in";

export type UpdateLayerParams = {
  /** Filling pattern. */
  fill_pattern?: FillPattern | null;
  /** Layer id. */
  id: number;
  /** Filling lines per mm. */
  lines_per_mm?: number | null;
  /** `line`, `fill`, `fill_and_line`, `cut` or `ignore`. */
  mode?: LayerMode | null;
  /** Name. */
  name?: string | null;
  /** Passes (at least 1). */
  passes?: number | null;
  /** `S` power. */
  power?: number | null;
  /** Speed, mm/min. */
  speed_mm_min?: number | null;
  /** Shown and planned. */
  visible?: boolean | null;
};

/** The whole view state. */
export type ViewState = {
  /** Open dialogs, bottom to top. */
  dialogs: Dialog[];
  /** The panel drawer is open (medium layout). */
  drawer_open: boolean;
  /**
   * The laser action waiting for the person's confirmation, if any (the fire
   * confirmation dialog is open while it is set).
   */
  fire_request?: FireRequest | null;
  /** Increased by `view.fit`: the UI fits the work area when it changes. */
  fit_request: number;
  /** Element with the keyboard focus (`canvas`, `console`... free text), if known. */
  focus?: string | null;
  /** Mode. */
  mode: Mode;
  /** Active panel of the dock. */
  panel: Panel;
  /** Toasts, oldest first (at most [`MAX_TOASTS`]). */
  toasts: Toast[];
  /** Active tool of the Design mode. */
  tool: Tool;
  /** Viewport, once the UI or a caller set it. */
  viewport?: Viewport | null;
};

/** What part of the table is shown: the world point at the centre and the zoom. */
export type Viewport = {
  /** Centre `[x, y]`, mm. */
  center: [number, number];
  /** Zoom, CSS pixels per mm. */
  zoom: number;
};

/** `machine.write_settings`. */
export type WriteSettingsParams = {
  /** Values by setting number (`{"110": "6000"}`). */
  settings: Record<string, never>;
};

/**
 * Permission tier of an action, from least to most powerful (`Safety` is special:
 * always allowed, because it only makes the machine safer).
 */
export type Tier = "safety" | "read" | "ui" | "edit" | "machine" | "laser";

/** Error of an action. */
export type ActionError = {
  kind: "unknown";
  message: string;
} | {
  kind: "invalid_params";
  message: string;
} | {
  kind: "permission_denied";
  message: {
    /** Action. */
    action: string;
    /** Tier it needs. */
    needed: Tier;
  };
} | {
  kind: "refused";
  message: string;
} | {
  kind: "failed";
  message: string;
};

/** Public description of an action. */
export type ActionSpec = {
  /** What it does (first line is the summary). */
  description: string;
  /** `namespace.name`. */
  name: string;
  /** JSON schema of the parameters. */
  params: unknown;
  /**
   * JSON schema of the result, when the registrant described it
   * ([`Registry::describe_result`]); front ends type the result as unknown otherwise.
   */
  result?: unknown;
  /** Tier. */
  tier: Tier;
};

/** A [`ServiceEvent`] as front ends receive it (JSON, tagged by `event`). */
export type EventMessage = {
  event: "connected";
  /** Transport description. */
  transport: string;
} | {
  event: "disconnected";
  /** Closed by the user (else: lost or failed). */
  user: boolean;
} | {
  /** The event. */
  data: Event;
  event: "host";
} | {
  event: "settings_changed";
} | {
  event: "program_loaded";
} | {
  /** What changed. */
  change: Change;
  event: "session";
  /** Revision after the change. */
  revision: number;
};

/** The whole settings file. */
export type Settings = {
  /** Automation (user-only). */
  automation?: AutomationSettings;
  /** Custom buttons of the machine panel (added in M4a; none by default). */
  buttons?: CustomButton[];
  /** Job custom code. */
  job?: JobSettings;
  /** Jog. */
  jog?: JogSettings;
  /** Machine connection. */
  machine?: MachineSettings;
  /** Safety (user-only; added in M4a). */
  safety?: SafetySettings;
  /** Appearance of the desktop app (added in M4a; files without it get the defaults). */
  ui?: UiSettings;
  /** Format version. */
  version?: number;
};

/** Every action: parameters, result and tier. */
export interface Actions {
  /** Console rows (sent commands, answers, messages). */
  "console.get": {
    params: ConsoleParams;
    result: ConsoleRow[];
    tier: "read";
  };
  /** Adds a layer of a colour (line, 1000 mm/min, power 1000, 1 pass unless given). One undo step. */
  "document.add_layer": {
    params: AddLayerParams;
    result: unknown;
    tier: "edit";
  };
  /** Draws a rectangle or an ellipse on a layer (default: the current layer) and selects it. One undo step. */
  "document.add_shape": {
    params: AddShapeParams;
    result: unknown;
    tier: "edit";
  };
  /** Writes text in the single-stroke font on a layer (default: the current layer) and selects it; the text stays editable (`document.set_text`). One undo step. */
  "document.add_text": {
    params: AddTextParams;
    result: unknown;
    tier: "edit";
  };
  /** Lines up objects (default: the selection, at least two) on the box around them: left, center_h, right, top, middle_v or bottom. One undo step. */
  "document.align": {
    params: AlignParams;
    result: unknown;
    tier: "edit";
  };
  /** Selects nothing. */
  "document.clear_selection": {
    params: NoParams;
    result: unknown;
    tier: "ui";
  };
  /** Deletes objects (default: the selection). One undo step. */
  "document.delete": {
    params: IdsParams;
    result: unknown;
    tier: "edit";
  };
  /** Copies objects (default: the selection), offset by `offset_mm`, and selects the copies. One undo step. */
  "document.duplicate": {
    params: DuplicateParams;
    result: unknown;
    tier: "edit";
  };
  /** Replaces the document with a `.fkproj` text (the undo history starts again). */
  "document.from_fkproj": {
    params: FkprojParams;
    result: unknown;
    tier: "edit";
  };
  /** The whole document (layers, objects with geometry and images), as in a `.fkproj` file. */
  "document.get": {
    params: NoParams;
    result: unknown;
    tier: "read";
  };
  /** Imports an SVG, DXF or image file into the document (format from the extension). One undo step. */
  "document.import": {
    params: LoadParams;
    result: unknown;
    tier: "edit";
  };
  /** Imports a file given as base64 bytes (`data`), or as `text` for SVG and DXF, into the document: SVG and DXF by colour layer, images on a layer of their own. One undo step. */
  "document.import_data": {
    params: ImportParams;
    result: unknown;
    tier: "edit";
  };
  /** The layer of a colour, created (line, 1000 mm/min, power 1000) when missing; it becomes the current layer. Creating it is one undo step. */
  "document.layer_for_color": {
    params: ColorParams;
    result: unknown;
    tier: "edit";
  };
  /** Moves a layer in the layer list (the order of layers of the same mode is the order they run). One undo step. */
  "document.move_layer": {
    params: MoveLayerParams;
    result: unknown;
    tier: "edit";
  };
  /** Moves objects (default: the selection) to another layer. One undo step. */
  "document.move_to_layer": {
    params: MoveToLayerParams;
    result: unknown;
    tier: "edit";
  };
  /** Starts an empty document (the undo history starts again). */
  "document.new": {
    params: NoParams;
    result: unknown;
    tier: "edit";
  };
  /** Opens a `.fkproj` project file (the undo history starts again). */
  "document.open": {
    params: LoadParams;
    result: unknown;
    tier: "edit";
  };
  /** Removes a layer and its objects. One undo step. */
  "document.remove_layer": {
    params: LayerIdParams;
    result: unknown;
    tier: "edit";
  };
  /** Saves the document as a `.fkproj` project file (written atomically). */
  "document.save": {
    params: LoadParams;
    result: unknown;
    tier: "edit";
  };
  /** Selects objects (replace, add to or remove from the selection). Unknown ids are ignored. */
  "document.select": {
    params: SelectParams;
    result: unknown;
    tier: "ui";
  };
  /** Selects every object. */
  "document.select_all": {
    params: NoParams;
    result: unknown;
    tier: "ui";
  };
  /** Chooses the layer new shapes and text go to. */
  "document.set_current_layer": {
    params: LayerIdParams;
    result: unknown;
    tier: "ui";
  };
  /** Changes a text object's text or font height (its position, rotation and scale stay). One undo step. */
  "document.set_text": {
    params: SetTextParams;
    result: unknown;
    tier: "edit";
  };
  /** The document as `.fkproj` text. */
  "document.to_fkproj": {
    params: NoParams;
    result: unknown;
    tier: "read";
  };
  /** Moves, scales, mirrors or rotates objects (default: the selection): `{translate}`, `{scale, pivot}`, `{rotate_deg, pivot}` or `{matrix}`. Images only move and scale. One undo step. */
  "document.transform": {
    params: TransformParams;
    result: unknown;
    tier: "edit";
  };
  /** Moves objects (default: the selection) by `dx`, `dy` mm. One undo step. */
  "document.translate": {
    params: TranslateParams;
    result: unknown;
    tier: "edit";
  };
  /** Changes a layer's name, mode, speed, power, passes, visibility or filling. One undo step. */
  "document.update_layer": {
    params: UpdateLayerParams;
    result: unknown;
    tier: "edit";
  };
  /** Cancels the pending laser request (the one given, or any). Always allowed. */
  "fire.cancel": {
    params: FireCancelParams;
    result: null;
    tier: "safety";
  };
  /** Asks to run a laser action: it opens the fire confirmation (checklist and countdown) and runs only when a person confirms on screen. Returns the pending request. */
  "fire.request": {
    params: FireRequestParams;
    result: FireRequest;
    tier: "machine";
  };
  /** Redoes the last undone change. */
  "history.redo": {
    params: NoParams;
    result: unknown;
    tier: "edit";
  };
  /** Undoes the last document change. */
  "history.undo": {
    params: NoParams;
    result: unknown;
    tier: "edit";
  };
  /** Stops streaming the job and sends `M5` (lines already in the board still run; use machine.stop to stop at once). Always allowed. */
  "job.abort": {
    params: NoParams;
    result: null;
    tier: "safety";
  };
  /** Runs the head around the bounds of the loaded program with the laser off (jog moves). */
  "job.frame": {
    params: FrameParams;
    result: null;
    tier: "machine";
  };
  /** Plans the document (vectors, then images; centerline uses the `autotrace` program) and loads it as the job. */
  "job.from_document": {
    params: NoParams;
    result: unknown;
    tier: "edit";
  };
  /** The loaded program (name, lines, estimated time, range). */
  "job.info": {
    params: NoParams;
    result: ProgramInfo | null;
    tier: "read";
  };
  /** Loads and analyzes a G-code file. */
  "job.load": {
    params: LoadParams;
    result: ProgramInfo;
    tier: "edit";
  };
  /** Loads and analyzes G-code given as text. */
  "job.load_text": {
    params: LoadTextParams;
    result: ProgramInfo;
    tier: "edit";
  };
  /** Runs the loaded program from a position, rebuilding position, power and modes first. Fires the laser. */
  "job.resume": {
    params: ResumeParams;
    result: null;
    tier: "laser";
  };
  /** Runs the loaded program from the start (header, program, footer, passes). Fires the laser. */
  "job.run": {
    params: RunParams;
    result: null;
    tier: "laser";
  };
  /** Connects to the machine on a serial port, or to the built-in emulator. */
  "machine.connect": {
    params: ConnectParams;
    result: null;
    tier: "machine";
  };
  /** Runs custom code (buttons, macros): `[expr]` evaluated, immediate characters sent at once. */
  "machine.custom_code": {
    params: CustomCodeParams;
    result: null;
    tier: "laser";
  };
  /** Closes the connection. */
  "machine.disconnect": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** Feed hold (pause the motion). Always allowed. */
  "machine.feed_hold": {
    params: NoParams;
    result: null;
    tier: "safety";
  };
  /** Runs the homing cycle (`$H`). */
  "machine.home": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** Work area, laser mode, highest power and laser module counters, from the board settings. */
  "machine.info": {
    params: NoParams;
    result: MachineInfo;
    tier: "read";
  };
  /** Jogs one step in a direction (laser off). */
  "machine.jog": {
    params: JogParams;
    result: null;
    tier: "machine";
  };
  /** Stops a continuous jog. Always allowed. */
  "machine.jog_stop": {
    params: NoParams;
    result: null;
    tier: "safety";
  };
  /** Jogs to a work position (laser off). */
  "machine.jog_to": {
    params: JogToParams;
    result: null;
    tier: "machine";
  };
  /** Serial ports found on this computer. */
  "machine.list_ports": {
    params: NoParams;
    result: string[];
    tier: "read";
  };
  /** Sets the override targets; the host steps the board towards them. */
  "machine.overrides": {
    params: OverrideParams;
    result: null;
    tier: "machine";
  };
  /** Reads the board settings again (`$$`). */
  "machine.read_settings": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** Resumes after a feed hold or a door (cycle start). */
  "machine.resume": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** Safety door (real-time 0x84): the board holds as if its door opened; resume with machine.resume. Always allowed. */
  "machine.safety_door": {
    params: NoParams;
    result: null;
    tier: "safety";
  };
  /** Selects the laser module in use (life counters). */
  "machine.select_laser": {
    params: SelectLaserParams;
    result: null;
    tier: "edit";
  };
  /** Sends one line of G-code or a `$` command (not during a job). It can turn the laser on. */
  "machine.send": {
    params: SendParams;
    result: null;
    tier: "laser";
  };
  /** Sets the current position as work zero (`G92 X0 Y0 Z0`). */
  "machine.set_zero": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** STOP: cancels running scripts, then soft resets the board (laser off, queues flushed). Always allowed. */
  "machine.stop": {
    params: NoParams;
    result: null;
    tier: "safety";
  };
  /** Sends a `$` command (`$$`, `$I`, `$H`, `$X`, `$N=V`, `$J=...`; not during a job). It cannot turn the laser on. */
  "machine.system_command": {
    params: SystemCommandParams;
    result: null;
    tier: "machine";
  };
  /** Unlocks the alarm state (`$X`). */
  "machine.unlock": {
    params: NoParams;
    result: null;
    tier: "machine";
  };
  /** Writes board settings (`$N=V`), one at a time; returns when the board answered all of them. */
  "machine.write_settings": {
    params: WriteSettingsParams;
    result: null;
    tier: "machine";
  };
  /** The session as front ends and agents read it: revision, selection, view, undo/redo labels, layers and objects without geometry. */
  "session.snapshot": {
    params: NoParams;
    result: unknown;
    tier: "read";
  };
  /** Reads the settings (all, or one dotted key). */
  "settings.get": {
    params: SettingsGetParams;
    result: unknown;
    tier: "read";
  };
  /** Changes one setting and saves the file. Automation settings are user-only and refused here. */
  "settings.set": {
    params: SettingsSetParams;
    result: null;
    tier: "edit";
  };
  /** Machine state, loaded program, issues and resume offer. */
  "state.get": {
    params: NoParams;
    result: State;
    tier: "read";
  };
  /** Closes a dialog (default: the top one). Closing the fire confirmation drops its laser request. */
  "view.close_dialog": {
    params: OptionalDialogParams;
    result: unknown;
    tier: "ui";
  };
  /** Closes the drawer when it shows this panel. */
  "view.close_panel": {
    params: PanelParams;
    result: unknown;
    tier: "ui";
  };
  /** Removes a toast. */
  "view.dismiss_toast": {
    params: ToastIdParams;
    result: unknown;
    tier: "ui";
  };
  /** Fits the work area in the canvas. */
  "view.fit": {
    params: NoParams;
    result: unknown;
    tier: "ui";
  };
  /** Records which element has the keyboard focus. */
  "view.focus": {
    params: FocusParams;
    result: unknown;
    tier: "ui";
  };
  /** The view: mode, tool, panel, dialogs, toasts, viewport, focus, the pending laser request. */
  "view.get": {
    params: NoParams;
    result: ViewState;
    tier: "read";
  };
  /** Opens a dialog on top of the others (dialogs are not modal: STOP stays reachable). */
  "view.open_dialog": {
    params: DialogParams;
    result: unknown;
    tier: "ui";
  };
  /** Shows a panel of the dock (`layers`, `object`, `machine`, `console`; opens the drawer in the medium layout). */
  "view.open_panel": {
    params: PanelParams;
    result: unknown;
    tier: "ui";
  };
  /** Switches between design and produce (produce shows the machine panel). */
  "view.set_mode": {
    params: ModeParams;
    result: unknown;
    tier: "ui";
  };
  /** Chooses the Design mode tool (select, rectangle, ellipse, text). */
  "view.set_tool": {
    params: ToolParams;
    result: unknown;
    tier: "ui";
  };
  /** Centres the view on a point (mm) at a zoom (CSS pixels per mm). */
  "view.set_viewport": {
    params: Viewport;
    result: unknown;
    tier: "ui";
  };
  /** Shows a short message (at most 3 at once); returns its id. */
  "view.toast": {
    params: ToastParams;
    result: number;
    tier: "ui";
  };
}

/** Action names. */
export type ActionName = keyof Actions;

